"""Credential-based S3 transfers for the qai_hub SDK.

When the server hands out short-lived, single-object AWS credentials, boto3's
transfer manager performs the upload or download directly, handling parallel
multipart transfers, retries and checksums. This module wraps that machinery so
the rest of the client can treat a credentials response the same way it treats a
pre-signed URL.
"""

from __future__ import annotations

import logging
import os
import shutil
import tempfile
import threading
from zipfile import ZipFile

import botocore.session
from botocore.client import Config
from s3transfer.manager import TransferConfig, TransferManager
from s3transfer.subscribers import BaseSubscriber

import qai_hub.public_api_pb2 as api_pb
from qai_hub import api_utils

_BLOCK_SIZE = 1024

# S3 throttles UploadPart/PUT requests per prefix. boto3's default transfer
# config (8 MiB parts, 10-way concurrency) turns a multi-GB upload into hundreds
# of concurrent part requests, which trips 503 SlowDown once a flurry of jobs
# uploads at once. Larger parts and lower concurrency keep the request rate near
# the pre-signed path this replaced; adaptive retries back off when throttled.
_MULTIPART_CHUNK_SIZE = 256 * 1024 * 1024
_TRANSFER_CONFIG = TransferConfig(
    multipart_threshold=_MULTIPART_CHUNK_SIZE,
    multipart_chunksize=_MULTIPART_CHUNK_SIZE,
    max_request_concurrency=4,
)


def _build_client(credentials: api_pb.S3Credentials):
    session = botocore.session.get_session()
    return session.create_client(
        "s3",
        region_name=credentials.region or None,
        aws_access_key_id=credentials.access_key_id,
        aws_secret_access_key=credentials.secret_access_key,
        aws_session_token=credentials.session_token,
        config=Config(
            signature_version="s3v4",
            s3={"use_accelerate_endpoint": credentials.use_transfer_acceleration},
            retries={"max_attempts": 10, "mode": "adaptive"},
        ),
    )


class _ProgressSubscriber(BaseSubscriber):
    def __init__(self, progress_bar):
        self._progress_bar = progress_bar
        # boto3 fires on_progress from several multipart worker threads at once,
        # and tqdm's update is not safe under concurrent callers; serialize them
        # so the bar advances monotonically instead of jumping.
        self._lock = threading.Lock()

    def on_progress(self, future, bytes_transferred, **kwargs):
        with self._lock:
            self._progress_bar.update(bytes_transferred)


def upload_file(
    credentials: api_pb.S3Credentials,
    path: str,
    verbose: bool,
    progress_bar_description: str,
    logger: logging.Logger | logging.LoggerAdapter | None = None,
) -> None:
    """Upload a local file to the credentials' bucket/key via boto3."""
    if logger is None:
        logger = logging.getLogger("s3_transfer")

    file_size = os.path.getsize(path)
    content_type = api_utils.guess_file_http_content_type(path)
    logger.info(f"Uploading {os.path.basename(path)}")

    client = _build_client(credentials)
    with (
        api_utils.get_progress_bar(
            progress_bar_description, file_size, _BLOCK_SIZE, verbose
        ) as progress_bar,
        TransferManager(client, config=_TRANSFER_CONFIG) as manager,
    ):
        future = manager.upload(
            str(path),
            credentials.bucket,
            credentials.key,
            extra_args={"ContentType": content_type},
            subscribers=[_ProgressSubscriber(progress_bar)],
        )
        future.result()


def download_file(
    credentials: api_pb.S3Credentials,
    filename: str,
    dst_path: str,
    verbose: bool,
    extract_if_zipped: bool = False,
) -> str:
    """Download the credentials' object, mirroring api_utils.download_file."""
    should_extract_file = extract_if_zipped and filename.endswith(".zip")
    filename, dst_path = api_utils._verify_download_path(
        filename, dst_path, should_extract_file
    )

    client = _build_client(credentials)
    file_size = client.head_object(Bucket=credentials.bucket, Key=credentials.key)[
        "ContentLength"
    ]

    # Download (and unzip) into a temporary directory first so a failed or
    # cancelled transfer never leaves a partial artifact at the destination.
    with (
        api_utils.get_progress_bar(filename, file_size, _BLOCK_SIZE, verbose) as bar,
        TransferManager(client, config=_TRANSFER_CONFIG) as manager,
        tempfile.TemporaryDirectory() as tmpdir,
    ):
        tmp_dst_path = os.path.join(tmpdir, os.path.basename(dst_path))
        future = manager.download(
            credentials.bucket,
            credentials.key,
            tmp_dst_path,
            subscribers=[_ProgressSubscriber(bar)],
        )
        future.result()

        if should_extract_file:
            extracted = os.path.join(tmpdir, "extracted")
            with ZipFile(tmp_dst_path, "r") as zipped:
                zipped.extractall(extracted)
            shutil.move(extracted, dst_path)
        else:
            shutil.move(tmp_dst_path, dst_path)

    return dst_path
